using Azure.AI.OpenAI;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation configuration for telemetry, quality, and compare modes.
/// </summary>
internal static class EvalSetup
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://your-resource.openai.azure.com/";

    private static readonly string DeploymentName =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var azureClient = new AzureOpenAIClient(
            new Uri(Endpoint),
            new DefaultAzureCredential());

        return azureClient
            .GetChatClient(DeploymentName)
            .AsIChatClient();
    }

    public static IList<IEvaluator> GetQualityEvaluators() =>
    [
        new CoherenceEvaluator(),
        new RelevanceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
        new CompletenessEvaluator(),
    ];

    public static ReportingConfiguration CreateReportingConfig(string runName)
    {
        var storage = new DiskBasedReportingStorage(
            Path.Combine(Directory.GetCurrentDirectory(), ".eval-results"));

        return new ReportingConfiguration(
            storage: storage,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            runName: runName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Telemetry mode: captures token usage, latency, and request metadata
/// for each scenario without running quality evaluators.
/// </summary>
[TestClass]
public sealed class TelemetryTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfig("telemetry");
    }

    [TestMethod]
    public async Task CaptureCoachResponse_Telemetry()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CaptureCoachResponse_Telemetry));

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "Give me a brief tip for staying focused while coding."),
        };

        var response = await client.GetResponseAsync(messages);

        // Record the turn so telemetry (tokens, latency) is persisted.
        scenario.Record(messages, response);
    }

    [TestMethod]
    public async Task CaptureMultiTurn_Telemetry()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CaptureMultiTurn_Telemetry));

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "What are three signs of burnout?"),
        };

        var response1 = await client.GetResponseAsync(messages);
        scenario.Record(messages, response1);

        messages.Add(new ChatMessage(ChatRole.Assistant, response1.Text));
        messages.Add(new ChatMessage(ChatRole.User, "How can I prevent the first one?"));

        var response2 = await client.GetResponseAsync(messages);
        scenario.Record(messages, response2);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Quality mode: runs AI-judged quality evaluators (coherence, relevance,
/// fluency, groundedness, completeness) on each scenario.
/// </summary>
[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfig("quality");
    }

    [TestMethod]
    public async Task CoachTip_MeetsQualityBar()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachTip_MeetsQualityBar));

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "Give me a concise tip for improving code review quality."),
        };

        var response = await client.GetResponseAsync(messages);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync(messages, response);

        // Assert all evaluator scores meet a minimum threshold.
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Metric '{numeric.Name}' scored {numeric.Value}, below threshold 3.");
            }
        }
    }

    [TestMethod]
    public async Task CoachAdvice_Grounded()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(CoachAdvice_Grounded));

        var client = EvalSetup.CreateChatClient();

        var context = """
            Research shows that taking short breaks every 25 minutes (Pomodoro technique)
            improves sustained attention and reduces mental fatigue.
            """;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System,
                $"You are a coaching assistant. Use this context:\n{context}"),
            new(ChatRole.User, "How should I structure my work sessions?"),
        };

        var response = await client.GetResponseAsync(messages);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync(messages, response);

        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= 3,
                    $"Metric '{numeric.Name}' scored {numeric.Value}, below threshold 3.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Compare mode: runs the same scenario with two different configurations
/// (e.g., prompts or models) and persists both runs so results can be
/// compared side-by-side in the evaluation report.
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private const string BaselinePrompt =
        "You are a coaching assistant. Be concise.";

    private const string CandidatePrompt =
        "You are an expert coaching assistant. Provide actionable, specific advice in 2-3 sentences.";

    [TestMethod]
    public async Task ComparePromptVariants()
    {
        var question = "How do I stop procrastinating on difficult tasks?";

        // Run baseline
        var baselineScores = await RunVariant("compare-baseline", BaselinePrompt, question);

        // Run candidate
        var candidateScores = await RunVariant("compare-candidate", CandidatePrompt, question);

        // Log comparison (in a real pipeline the report viewer shows this side-by-side).
        foreach (var (name, baseVal) in baselineScores)
        {
            if (candidateScores.TryGetValue(name, out var candVal))
            {
                Console.WriteLine($"[Compare] {name}: baseline={baseVal:F1}, candidate={candVal:F1}, delta={candVal - baseVal:+0.0;-0.0}");
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var question = "What's a good morning routine for productivity?";

        var lowTemp = await RunVariant("compare-temp-0.3", BaselinePrompt, question, temperature: 0.3f);
        var highTemp = await RunVariant("compare-temp-0.9", BaselinePrompt, question, temperature: 0.9f);

        foreach (var (name, lowVal) in lowTemp)
        {
            if (highTemp.TryGetValue(name, out var highVal))
            {
                Console.WriteLine($"[Compare] {name}: temp=0.3 → {lowVal:F1}, temp=0.9 → {highVal:F1}");
            }
        }
    }

    private static async Task<Dictionary<string, float>> RunVariant(
        string runName,
        string systemPrompt,
        string userQuestion,
        float? temperature = null)
    {
        var config = EvalSetup.CreateReportingConfig(runName);

        await using var scenario = await config.CreateScenarioRunAsync(
            scenarioName: $"{runName}_scenario");

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, userQuestion),
        };

        var options = temperature.HasValue
            ? new ChatOptions { Temperature = temperature.Value }
            : null;

        var response = await client.GetResponseAsync(messages, options);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync(messages, response);

        var scores = new Dictionary<string, float>();
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric && numeric.Value.HasValue)
            {
                scores[numeric.Name] = (float)numeric.Value.Value;
            }
        }

        return scores;
    }
}

