    {
        var storage = new DiskBasedReportingStorage(
            Path.Combine(Directory.GetCurrentDirectory(), ".eval-results"));

        return new ReportingConfiguration(
            storage: storage,
            evaluators: GetQualityEvaluators(),
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            runName: runName);
    }
}

