using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Scenarios;

/// <summary>
/// Compare mode: runs the same scenario with two different configurations
/// (e.g., prompts or models) and persists both runs so results can be
/// compared side-by-side in the evaluation report.
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private const string BaselinePrompt =
        "You are a coaching assistant. Be concise.";

    private const string CandidatePrompt =
        "You are an expert coaching assistant. Provide actionable, specific advice in 2-3 sentences.";

    [TestMethod]
    public async Task ComparePromptVariants()
    {
        var question = "How do I stop procrastinating on difficult tasks?";

        var baselineScores = await RunVariant("compare-baseline", BaselinePrompt, question);
        var candidateScores = await RunVariant("compare-candidate", CandidatePrompt, question);

        foreach (var (name, baseVal) in baselineScores)
        {
            if (candidateScores.TryGetValue(name, out var candVal))
            {
                Console.WriteLine($"[Compare] {name}: baseline={baseVal:F1}, candidate={candVal:F1}, delta={candVal - baseVal:+0.0;-0.0}");
            }
        }
    }

    [TestMethod]
    public async Task CompareTemperatureSettings()
    {
        var question = "What's a good morning routine for productivity?";

        var lowTemp = await RunVariant("compare-temp-0.3", BaselinePrompt, question, temperature: 0.3f);
        var highTemp = await RunVariant("compare-temp-0.9", BaselinePrompt, question, temperature: 0.9f);

        foreach (var (name, lowVal) in lowTemp)
        {
            if (highTemp.TryGetValue(name, out var highVal))
            {
                Console.WriteLine($"[Compare] {name}: temp=0.3 → {lowVal:F1}, temp=0.9 → {highVal:F1}");
            }
        }
    }

    private static async Task<Dictionary<string, float>> RunVariant(
        string runName,
        string systemPrompt,
        string userQuestion,
        float? temperature = null)
    {
        var config = EvalSetup.CreateReportingConfig(runName);

        await using var scenario = await config.CreateScenarioRunAsync(
            scenarioName: $"{runName}_scenario");

        var client = EvalSetup.CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, systemPrompt),
            new(ChatRole.User, userQuestion),
        };

        var options = temperature.HasValue
            ? new ChatOptions { Temperature = temperature.Value }
            : null;

        var response = await client.GetResponseAsync(messages, options);
        scenario.Record(messages, response);

        await scenario.EvaluateAsync(messages, response);

        var scores = new Dictionary<string, float>();
        foreach (var metric in scenario.GetEvaluationResults())
        {
            if (metric is NumericMetric numeric && numeric.Value.HasValue)
            {
                scores[numeric.Name] = (float)numeric.Value.Value;
            }
        }

        return scores;
    }
}

